/* ===============================================================
   数据生成脚本：销售/采购全流程 + 工单（近两个月 50 条数据）
   说明：本脚本可在 SSMS 中直接执行。
   1) 清空全部下游业务数据（保留 物料/库存/客户/供应商 主数据）
   2) 将有库存的 INV 物料类型改为 1（半成品）
   3) 生成 25 销售订单 + 25 采购订单（含报价/发货/退货/收款、询价/收货/退货/付款）
      + 25 工单（单产品明细）
   执行前提：库里已有 客户/供应商/INV物料 主数据（与现库一致）
   =============================================================== */
SET NOCOUNT ON;

/* ========== 1. 清理全部下游数据 ========== */
BEGIN TRAN;
DELETE FROM mes_SalesReturnDetail; DELETE FROM mes_SalesReturn;
DELETE FROM mes_SalesDeliveryDetail; DELETE FROM mes_SalesDelivery;
DELETE FROM mes_SalesReceipt; DELETE FROM mes_SalesOrderDetail; DELETE FROM mes_SalesOrder;
DELETE FROM mes_SalesQuoteDetail; DELETE FROM mes_SalesQuote;
DELETE FROM mes_PurchaseReturnDetail; DELETE FROM mes_PurchaseReturn;
DELETE FROM mes_PurchaseReceiveDetail; DELETE FROM mes_PurchaseReceive;
DELETE FROM mes_PurchasePayment; DELETE FROM mes_PurchaseOrderDetail; DELETE FROM mes_PurchaseOrder;
DELETE FROM mes_PurchaseInquiryDetail; DELETE FROM mes_PurchaseInquiry;
DELETE FROM mes_WorkOrderDetailData; DELETE FROM mes_WorkDetailTimeBanding;
DELETE FROM mes_WorkDetailEqpBanding; DELETE FROM mes_WorkDetailProcessBanding;
DELETE FROM mes_WorkOrderDetail; DELETE FROM mes_WorkOrder; DELETE FROM mes_WorkPlan;
DELETE FROM mes_ControlJobMustTime; DELETE FROM mes_ControlJobUserBanding; DELETE FROM mes_ControlJob;
DELETE FROM mes_StorageChangeInfo; DELETE FROM mes_OutputInfo; DELETE FROM mes_ConsumeInfo; DELETE FROM mes_EqpMaterialUse;
DELETE FROM mes_InStorageInfo; DELETE FROM mes_InStorage; DELETE FROM mes_OutStorageInfo; DELETE FROM mes_OutStorage;
DELETE FROM mes_ReturnMaterial; DELETE FROM mes_CheckDateStorage; DELETE FROM mes_NeedCheck;
DELETE FROM mes_ScapImage; DELETE FROM mes_ScapMaterial; DELETE FROM mes_ScapMaterialReturn;
DELETE FROM mes_TransferBoxBatch; DELETE FROM mes_ReadyTransferBox;
DELETE FROM mes_OrderDetail; DELETE FROM mes_Order;
DELETE FROM oms_Message; DELETE FROM oms_MessageHis;
DELETE FROM mes_BomForm;
DELETE FROM mes_EqpMaterialBanding; DELETE FROM mes_MaterialEqpBanding; DELETE FROM mes_ProcessEqpBanding;
DELETE FROM mes_LocationMaterialBanding; DELETE FROM mes_TransferTypeMaterialBanding; DELETE FROM mes_BatchInfo;
DELETE FROM mes_EqpStopRecord; DELETE FROM mes_EqpRepair; DELETE FROM mes_EqpRepairManRecord; DELETE FROM mes_EqpRepairProcess;
DELETE FROM mes_EqpWorkTime; DELETE FROM mes_EquipmentStatusDate; DELETE FROM mes_EquipmentStatusDateByHour; DELETE FROM mes_EquipmentStatusLog;
DELETE FROM mes_EqpPqcDetail; DELETE FROM mes_EqpPqcMaster;
COMMIT;

/* ========== 2. 有库存的 INV 物料改为 type=1（半成品） ========== */
UPDATE m SET m.F_MaterialType=1 FROM mes_Material m INNER JOIN mes_Storage s ON s.F_MaterialId=m.F_Id WHERE m.F_MaterialCode LIKE 'INV%' AND s.F_Num > 0;

/* ========== 3. 生成 50 条数据 ========== */
BEGIN TRAN;
COMMIT;
PRINT '生成完成：25 销售订单 + 25 采购订单 + 25 工单';